details.command:
kubectl exec -n default $POD -- sh -c 'command -v curl bash -c "curl -s -o /dev/null -w '%{http_code}
' http://127.0.0.1:8080/; echo "HTTP body:"; head -5 /dev/tcp/127.0.0.1/8080"; echo "---tcp-socket---"; sh -c "exec 3<>/dev/tcp/127.0.0.1/8080; printf 'GET / HTTP/1.1


' >&3; tail -5 <&3" 2>&1'

POD=$(kubectl get pod -n default -l app=app -o jsonpath='{.items[0].metadata.name}'); echo "app-pod=$POD"; echo "--- app pod state ---"; kubectl get pod -n default $POD; kubectl get deploy,sts -n default; echo "--- volumes (no claim) ---"; kubectl get pvc -n default; echo "--- app container mounts ---"; kubectl get pod -n default $POD -o jsonpath='{range .spec.containers[*].volumeMounts[*]} name={.name} mountPath={.mountPath} image={.image} writable={.writableRoot} readOnly={.readOnlyRoot} readOnlyRootFilesystem={.readOnlyRootFilesystem} mountSharing={.name}{"
"}{end}'; echo; echo "--- serving from other pod (app pod) ---"; kubectl exec -n default $POD -- sh -c 'command -v curl curl bash -c "curl -s -m 5 -o /dev/null -w '%{http_code}
' http://10.244.0.2:8080/ ; echo "== body =="; head -2 /dev/tcp/127.0.0.1/8080"' 2>&1; echo "== body from nginx-curl =="; POD2=$(kubectl get pods -n default -l app=app -o jsonpath='{.items[0].metadata.name}'); kubectl exec -n default $POD2 -- sh -c 'curl -s -m 5 -o /dev/null -w "%{http_code}
" http://10.244.0.2:8080/ ; echo "== body =="; head -2 /dev/tcp/127.0.0.1/8080"' 2>&1
